CREATE OR REPLACE FUNCTION public.adjust_personnel_salary(p_personnel_id uuid, p_type text, p_delta numeric, p_reason text, p_effective_date date DEFAULT CURRENT_DATE, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_personnel record;
    v_amount_before numeric;
    v_amount_after numeric;
    v_signed_delta numeric;
    v_actor_id uuid := public.current_user_profile_id();
    v_actor_name text;
    v_tenant_id uuid;
    v_adjustment public.salary_adjustments;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification (0055 pattern) ─────────────────────────────
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'adjust_personnel_salary: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer']) then
            raise exception 'adjust_personnel_salary: only super_admin / financial_officer may adjust salaries';
        end if;
    end if;

    -- ── Input validation (mirrors the desktop UI's mandatory-reason rule) ─
    if p_type not in ('raise', 'cut', 'bonus', 'deduction') then
        raise exception 'adjust_personnel_salary: invalid adjustment type %', p_type;
    end if;
    if p_delta is null or p_delta <= 0 then
        raise exception 'adjust_personnel_salary: the adjustment amount must be positive';
    end if;
    if p_reason is null or length(trim(p_reason)) < 5 then
        raise exception 'adjust_personnel_salary: a formal justification of at least 5 characters is mandatory';
    end if;

    -- ── Lock the personnel row (atomic read-modify-write) ───────────────
    select * into v_personnel
      from public.personnel
     where id = p_personnel_id
     for update;

    if not found then
        raise exception 'adjust_personnel_salary: personnel record % not found', p_personnel_id;
    end if;

    v_tenant_id := v_personnel.tenant_id;

    -- Tenant guard (SEC-112 lesson): the caller's working tenant must own
    -- the personnel row. Global admins (tenant-less profiles) and the
    -- service_role are the 0055-trusted exemptions.
    if not v_caller_is_service_role
       and public.current_tenant_id() is not null
       and public.current_tenant_id() <> v_tenant_id then
        raise exception 'adjust_personnel_salary: cross-tenant adjustment refused (personnel tenant % does not match the caller''s working tenant)', v_tenant_id;
    end if;

    v_amount_before := coalesce(v_personnel.base_salary, 0);

    -- Actor display name: the UI-passed name wins, else the profile's
    -- display_name, else a neutral fallback.
    select coalesce(display_name, '') into v_actor_name
      from public.user_profiles
     where id = v_actor_id
       and v_actor_id is not null;
    v_actor_name := coalesce(nullif(trim(coalesce(p_actor_name, '')), ''), nullif(v_actor_name, ''), 'Admin');

    -- ── The four adjustment semantics (the blueprint's table) ───────────
    -- INVARIANT: delta = amount_after - amount_before on every row (the
    -- table CHECK enforces it for raise/cut). For a FLOORED cut the delta
    -- records the reduction that ACTUALLY happened, not the requested
    -- magnitude — a deviation from the blueprint's "-abs(p_delta)" recorded
    -- here because the blueprint's version violates its own row invariant
    -- (amount_after = amount_before + delta) whenever the floor engages.
    if p_type = 'raise' then
        v_amount_after := v_amount_before + abs(p_delta);
        v_signed_delta := abs(p_delta);
    elsif p_type = 'cut' then
        v_amount_after := greatest(0, v_amount_before - abs(p_delta));
        v_signed_delta := v_amount_after - v_amount_before;
    elsif p_type = 'bonus' then
        v_amount_after := v_amount_before;            -- one-off: base unchanged
        v_signed_delta := abs(p_delta);
    else -- 'deduction'
        v_amount_after := v_amount_before;            -- one-off: base unchanged
        v_signed_delta := -abs(p_delta);
    end if;

    -- ── Update the base salary (raise/cut only) ─────────────────────────
    if p_type in ('raise', 'cut') then
        update public.personnel
           set base_salary = v_amount_after,
               updated_at = now()
         where id = p_personnel_id;
    end if;

    -- ── The immutable adjustment row ─────────────────────────────────────
    insert into public.salary_adjustments (
        tenant_id, personnel_id, type, amount_before, amount_after,
        delta, reason, effective_date, approved_by, approved_by_name
    ) values (
        v_tenant_id, p_personnel_id, p_type, v_amount_before, v_amount_after,
        v_signed_delta, trim(p_reason), coalesce(p_effective_date, current_date), v_actor_id, v_actor_name
    )
    returning * into v_adjustment;

    -- ── Master audit log (0014) ──────────────────────────────────────────
    perform public.write_audit_log(
        p_tenant_id   := v_tenant_id,
        p_action      := 'personnel.salary_adjusted',
        p_entity_type := 'personnel',
        p_entity_id   := p_personnel_id,
        p_actor_id    := v_actor_id,
        p_actor_name  := v_actor_name,
        p_before_json := jsonb_build_object('salary', v_amount_before),
        p_after_json  := jsonb_build_object('salary', v_amount_after, 'type', p_type, 'delta', v_signed_delta, 'reason', trim(p_reason)),
        p_note        := format('Salary adjusted (%s: %s DZD)', p_type, v_signed_delta)
    );

    return jsonb_build_object(
        'adjustment', to_jsonb(v_adjustment),
        'base_salary_after', v_amount_after
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_expense(p_tenant_id uuid, p_ticket_id uuid, p_approver_profile_id uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_ticket record;
    v_audit_id uuid;
    v_caller_is_service_role boolean := coalesce(auth.jwt() ->> 'role', '') = 'service_role';
begin
    -- ── Caller verification + actor binding (SEC-118, the 0055 pattern) ──
    if not v_caller_is_service_role then
        if auth.uid() is null then
            raise exception 'approve_expense: an authenticated caller is required';
        end if;
        if not public.has_any_role(array['super_admin', 'financial_officer', 'manager']) then
            raise exception 'approve_expense: only super_admin / financial_officer / manager may approve expenses';
        end if;
        if p_approver_profile_id is distinct from public.current_user_profile_id() then
            raise exception 'approve_expense: p_approver_profile_id must be the caller''s own profile (SEC-118 actor binding) — approvals cannot be recorded in another profile''s name';
        end if;
    end if;

    select * into v_ticket from public.expense_tickets where id = p_ticket_id and tenant_id = p_tenant_id;
    if not found then raise exception 'Expense ticket not found'; end if;

    if v_ticket.submitted_by = p_approver_profile_id then
        raise exception 'Self-approval is forbidden (plan §08)';
    end if;

    if v_ticket.status <> 'pending_approval' then
        raise exception 'Ticket is not pending approval (current: %)', v_ticket.status;
    end if;

    update public.expense_tickets
       set status = 'approved_funds_released',
           approved_by = p_approver_profile_id,
           approved_at = now(),
           approval_note = p_note,
           disbursed_at = now(),
           updated_at = now()
     where id = p_ticket_id;

    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'expense.approve',
        p_entity_type := 'expense_ticket',
        p_entity_id := p_ticket_id,
        p_actor_id := p_approver_profile_id,
        p_after_json := jsonb_build_object('status', 'approved_funds_released', 'note', p_note)
    );

    return v_audit_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_entity   text;
    v_action   text;
    v_entity_id uuid;
    v_tenant   uuid;
    v_actor_id  uuid;
    v_actor_name text;
    v_actor_role text;
    v_before   jsonb;
    v_after    jsonb;
    v_row      jsonb;
begin
    -- Snapshots (updated_at stripped — the touch trigger always rewrites it).
    if TG_OP = 'UPDATE' then
        v_before := to_jsonb(OLD) - 'updated_at';
        v_after  := to_jsonb(NEW) - 'updated_at';
        -- No-op guard: only the touch timestamp changed → not a mutation.
        if v_before is not distinct from v_after then
            return null;
        end if;
    elsif TG_OP = 'INSERT' then
        v_before := null;
        v_after  := to_jsonb(NEW) - 'updated_at';
    else -- DELETE
        v_before := to_jsonb(OLD) - 'updated_at';
        v_after  := null;
    end if;

    v_row := case TG_OP when 'DELETE' then to_jsonb(OLD) else to_jsonb(NEW) end;

    -- Entity + action mapping (AuditActions wire-code style: entity.action).
    v_entity := (case TG_TABLE_NAME
        when 'parents'                   then 'parent'
        when 'students'                  then 'student'
        when 'pricing_configs'           then 'pricing_config'
        when 'grade_level_tuition'       then 'pricing_grade'
        when 'transport_destinations'    then 'pricing_transport'
        when 'complementary_services'    then 'pricing_complementary_service'
        when 'additional_services'       then 'pricing_additional_service'
        when 'discounts'                 then 'pricing_discount'
        else TG_TABLE_NAME
    end);
    v_action := v_entity || '.' ||
        (case TG_OP when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end);

    v_entity_id := (v_row ->> 'id')::uuid;

    -- Tenant resolution: CRM rows carry tenant_id; pricing children resolve
    -- through their pricing_config.
    if TG_TABLE_NAME in ('parents', 'students', 'pricing_configs') then
        v_tenant := (v_row ->> 'tenant_id')::uuid;
    else
        v_tenant := (select pc.tenant_id
                       from public.pricing_configs pc
                      where pc.id = (v_row ->> 'pricing_config_id')::uuid);
    end if;
    if v_tenant is null then
        v_tenant := public.current_tenant_id();
    end if;
    -- Defensive: an unresolvable tenant must NEVER roll back the business
    -- write — skip the audit row and warn (observable in Postgres logs).
    if v_tenant is null then
        raise warning 'audit_row_change: tenant unresolvable for % %', TG_OP, TG_TABLE_NAME;
        return null;
    end if;

    -- Actor attribution (auth context; NULL under service-role jobs).
    select id into v_actor_id
      from public.user_profiles
     where auth_user_id = auth.uid()
     limit 1;
    if v_actor_id is not null then
        select coalesce(display_name, email) into v_actor_name
          from public.user_profiles
         where id = v_actor_id;
        select r.code into v_actor_role
          from public.role_assignments ra
          join public.roles r on r.id = ra.role_id
         where ra.user_profile_id = v_actor_id
           and ra.revoked_at is null
         order by r.code
         limit 1;
    else
        v_actor_name := 'System';
        v_actor_role := null;
    end if;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := v_action,
        p_entity_type := v_entity,
        p_entity_id   := v_entity_id,
        p_actor_id    := v_actor_id,
        p_actor_name  := v_actor_name,
        p_actor_role  := v_actor_role,
        p_before_json := v_before,
        p_after_json  := v_after,
        p_note        := 'Capture automatique (déclencheur ' || TG_OP || ' sur ' || TG_TABLE_NAME || ')'
    );

    return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.batch_register_family(p_tenant_id uuid, p_parent jsonb, p_students jsonb, p_actor_profile_id uuid, p_activation_code text DEFAULT NULL::text)
 RETURNS TABLE(parent_id uuid, student_ids uuid[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_parent_id uuid;
    v_student_ids uuid[] := '{}';
    v_student_id uuid;
    v_student jsonb;
    v_parent_code text;
    v_student_code text;
    v_seq integer;
    v_activation_code text;
    v_audit_id uuid;
begin
    -- DRIFT-001 / T-115 (migration 0065): the parent code is CANONICAL and
    -- DETERMINISTIC — FNV-1a of the identity fields, exactly like the
    -- desktop's SupabaseParentRepository and the approve-signup-request EF.
    -- The unique (tenant_id, parent_code) constraint then refuses duplicate
    -- family registrations for the same identity — that refusal IS the
    -- canonical idempotency contract ("the dedup match IS the code").
    if coalesce(btrim(p_parent->>'primary_phone'), '') = ''
       and coalesce(btrim(p_parent->>'display_name'), '') = ''
       and coalesce(btrim(p_parent->>'first_name'), '') = ''
       and coalesce(btrim(p_parent->>'last_name'), '') = '' then
        raise exception 'batch_register_family: parent identity fields required (primary_phone / display_name / first_name / last_name) — the canonical code generator has no random fallback (DRIFT-001, migration 0065)';
    end if;

    v_parent_code := public.fn_deterministic_parent_code(
        extract(year from now())::int,
        p_parent->>'primary_phone',
        p_parent->>'display_name',
        p_parent->>'first_name',
        p_parent->>'last_name'
    );

    -- Insert parent
    insert into public.parents (
        tenant_id, parent_code, first_name, last_name, primary_phone,
        secondary_phone, email, national_id, occupation, address, city,
        postal_code, relationship, notes, is_active, created_at, updated_at
    ) values (
        p_tenant_id, v_parent_code,
        p_parent->>'first_name', p_parent->>'last_name', p_parent->>'primary_phone',
        p_parent->>'secondary_phone', p_parent->>'email', p_parent->>'national_id',
        p_parent->>'occupation', p_parent->>'address', p_parent->>'city',
        p_parent->>'postal_code', p_parent->>'relationship', p_parent->>'notes',
        true, now(), now()
    )
    returning id into v_parent_id;

    -- Insert students (sequential ELV-{year}-{6-digit} — canonical student
    -- format per core/format/id.ts; DRIFT-001's RPC finding targets the
    -- PARENT code, the deterministic-ELV variant belongs to the
    -- sync/import upsert paths).
    for v_student in select * from jsonb_array_elements(p_students)
    loop
        v_seq := nextval('public.student_seq');
        v_student_code := 'ELV-' || extract(year from now())::text || '-' || lpad(v_seq::text, 6, '0');

        insert into public.students (
            tenant_id, parent_id, student_code, first_name, middle_name, last_name,
            date_of_birth, gender, grade_level_id, class_id, enrollment_date,
            enrollment_status, medical_notes, is_active, created_at, updated_at
        ) values (
            p_tenant_id, v_parent_id, v_student_code,
            v_student->>'first_name', v_student->>'middle_name', v_student->>'last_name',
            (v_student->>'date_of_birth')::date,
            v_student->>'gender',
            nullif(v_student->>'grade_level_id', '')::uuid,
            nullif(v_student->>'class_id', '')::uuid,
            current_date, 'enrolled', v_student->>'medical_notes',
            true, now(), now()
        )
        returning id into v_student_id;
        v_student_ids := array_append(v_student_ids, v_student_id);
    end loop;

    -- Issue activation code (or use provided one).
    -- DRIFT-001 / T-115: the DEFAULT is now the canonical DETERMINISTIC code
    -- (same family -> same activation code on retry). Collision fallback:
    -- the 6-digit space can collide across parents in a tenant (~3.7% at
    -- 259 parents); on a collision with a DIFFERENT parent's unbound code,
    -- fall back to the random-with-uniqueness generator (safety first).
    if p_activation_code is not null then
        v_activation_code := p_activation_code;
    else
        v_activation_code := public.fn_deterministic_activation_code(v_parent_code, p_tenant_id);
        if exists (
            select 1 from public.activation_codes ac
             where ac.tenant_id = p_tenant_id
               and ac.code = v_activation_code
               and ac.bound_to_auth_user_id is null
               and ac.parent_id is distinct from v_parent_id
        ) then
            v_activation_code := public.generate_activation_code(p_tenant_id);
        end if;
    end if;

    insert into public.activation_codes (
        tenant_id, code, parent_id, issued_by, issued_at, expires_at
    ) values (
        p_tenant_id, v_activation_code, v_parent_id, p_actor_profile_id, now(), now() + interval '30 days'
    );

    -- Write audit log
    v_audit_id := public.write_audit_log(
        p_tenant_id := p_tenant_id,
        p_action := 'parent.batch_register',
        p_entity_type := 'parent',
        p_entity_id := v_parent_id,
        p_actor_id := p_actor_profile_id,
        p_before_json := null,
        p_after_json := jsonb_build_object('parent_id', v_parent_id, 'student_ids', v_student_ids, 'activation_code', v_activation_code, 'parent_code', v_parent_code, 'code_rule', 'deterministic_fnv1a_0065'),
        p_note := 'Atomic batch registration: parent + ' || cardinality(v_student_ids) || ' students (canonical deterministic parent code, migration 0065)'
    );

    return query select v_parent_id, v_student_ids;
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_activation_code(p_tenant_id uuid, p_code text, p_auth_user_id uuid)
 RETURNS TABLE(parent_id uuid, parent_full_name text, student_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_activation record;
    v_parent_id uuid;
    v_existing_auth_user_id uuid;
    v_caller_is_service_role boolean;
begin
    -- ── SEC-110: caller verification ─────────────────────────────────
    -- Direct PostgREST callers (user JWT) must bind THEMSELVES only.
    -- The bind-activation-code Edge Function calls via service_role
    -- after verifying the caller's JWT (ctx.userId = the verified
    -- auth.users.id) — service_role is trusted server-side code.
    -- Anonymous / forged-token callers: auth.uid() IS NULL → rejected.
    v_caller_is_service_role := coalesce(auth.jwt() ->> 'role', '') = 'service_role';

    if p_auth_user_id is null then
        raise exception 'bind_activation_code: p_auth_user_id is required (SEC-110)';
    end if;

    if not v_caller_is_service_role
       and (auth.uid() is null or p_auth_user_id <> auth.uid()) then
        raise exception 'bind_activation_code: p_auth_user_id must match the authenticated caller (SEC-110)';
    end if;

    -- Lock the activation code row
    select * into v_activation
      from public.activation_codes
     where tenant_id = p_tenant_id
       and code = p_code
       and bound_to_auth_user_id is null
     for update;

    if not found then
        raise exception 'Invalid or already-used activation code';
    end if;

    if v_activation.expires_at < now() then
        raise exception 'Activation code has expired';
    end if;

    v_parent_id := v_activation.parent_id;

    -- ── STUDENT-101: silent re-bind guard ────────────────────────────
    -- Refuse to transfer a parent record that is already bound to a
    -- DIFFERENT auth user. Re-binding the SAME user (retry after a
    -- partial failure) stays allowed.
    select auth_user_id into v_existing_auth_user_id
      from public.parents
     where id = v_parent_id
     for update;

    if v_existing_auth_user_id is not null
       and v_existing_auth_user_id <> p_auth_user_id then
        raise exception 'bind_activation_code: parent % is already bound to another account — contact the school office', v_parent_id;
    end if;

    -- Mark the code as bound
    update public.activation_codes
       set bound_to_auth_user_id = p_auth_user_id,
           bound_at = now()
     where id = v_activation.id;

    -- Bind the auth.users.id to the parent record
    update public.parents
       set auth_user_id = p_auth_user_id
     where id = v_parent_id;

    -- ── PARENT-103: audit the direct-RPC path ────────────────────────
    -- The EF path already writes its own richer audit entry
    -- (activation_code.bind, with request id) AFTER this RPC returns;
    -- auditing from here too would duplicate it. Direct PostgREST
    -- callers bypass the EF entirely, so THIS path is audited here.
    if not v_caller_is_service_role then
        insert into public.audit_logs (
            id, tenant_id, action, entity_type, entity_id,
            actor_id, actor_name, after_json, note, occurred_at
        ) values (
            public.gen_uuid(), p_tenant_id, 'activation_code.bind_rpc', 'parent', v_parent_id,
            null, 'direct-rpc-caller',
            jsonb_build_object('activation_code', p_code, 'auth_user_id', p_auth_user_id),
            'bind_activation_code called directly via PostgREST (not via the Edge Function)',
            now()
        );
    end if;

    -- Return parent + student count for the response
    return query
        select p.id as parent_id,
               (p.first_name || ' ' || p.last_name) as parent_full_name,
               count(s.id)::bigint as student_count
          from public.parents p
          left join public.students s on s.parent_id = p.id and s.deleted_at is null
         where p.id = v_parent_id
         group by p.id, p.first_name, p.last_name;
end;
$function$

CREATE OR REPLACE FUNCTION public.compute_assessments_subject_average()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_c1  NUMERIC;
    v_c2  NUMERIC;
    v_c3  NUMERIC;
    v_cc  NUMERIC;
    v_num NUMERIC := 0;
    v_den NUMERIC := 0;
BEGIN
    -- Legacy row with no component marks at all — leave the stored value.
    IF NEW.devoir1 IS NULL AND NEW.devoir2 IS NULL
       AND NEW.examen IS NULL AND NEW.cc IS NULL THEN
        RETURN NEW;
    END IF;

    -- Weight snapshots (the values in force at entry — ADR-018 §3).
    v_c1 := COALESCE(NEW.coefficient_devoir1, 1.00);
    v_c2 := COALESCE(NEW.coefficient_devoir2, 1.00);
    v_c3 := COALESCE(NEW.coefficient_examen, 2.00);
    v_cc := COALESCE(NEW.coefficient_cc, 0.00);

    -- A positive-weight component is REQUIRED: any missing one makes the
    -- average not computable (NULL — the T-336 honesty rule).
    IF v_c1 > 0 AND NEW.devoir1 IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_c2 > 0 AND NEW.devoir2 IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_c3 > 0 AND NEW.examen IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;
    IF v_cc > 0 AND NEW.cc      IS NULL THEN NEW.subject_average := NULL; RETURN NEW; END IF;

    IF v_c1 > 0 THEN v_num := v_num + NEW.devoir1 * v_c1; v_den := v_den + v_c1; END IF;
    IF v_c2 > 0 THEN v_num := v_num + NEW.devoir2 * v_c2; v_den := v_den + v_c2; END IF;
    IF v_c3 > 0 THEN v_num := v_num + NEW.examen * v_c3; v_den := v_den + v_c3; END IF;
    IF v_cc > 0 THEN v_num := v_num + NEW.cc      * v_cc; v_den := v_den + v_cc; END IF;

    IF v_den = 0 THEN
        NEW.subject_average := NULL;
        RETURN NEW;
    END IF;

    NEW.subject_average := ROUND((v_num / v_den)::numeric, 2);
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_grade_subject_average()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_term integer;
    v_class_subject_id uuid := new.class_subject_id;
    v_student_id uuid := new.student_id;
    v_d1 numeric;
    v_d2 numeric;
    v_ex numeric;
begin
    -- Determine the term from the assessment
    select term into v_term from public.assessments where id = new.assessment_id;
    if v_term is null then
        return new;
    end if;

    -- Look up D1, D2, Examen scores for this student/subject/term
    select g.score into v_d1
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'devoir_1';

    select g.score into v_d2
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'devoir_2';

    select g.score into v_ex
      from public.grades g
      join public.assessments a on a.id = g.assessment_id
     where g.student_id = v_student_id
       and g.class_subject_id = v_class_subject_id
       and a.term = v_term
       and a.kind = 'examen';

    -- BUG FIX (TIER 4): the lookups above only see rows ALREADY IN THE TABLE.
    -- When the completing mark (e.g. the examen) is being INSERTED, its own
    -- lookup returned NULL and the average was never computed — the compute
    -- path could only fire on a subsequent UPDATE. NEW's own score is now
    -- substituted for its kind so the average is set on the completing row.
    if new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'devoir_1'
           and class_subject_id = v_class_subject_id
    ) then
        v_d1 := new.score;
    elsif new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'devoir_2'
           and class_subject_id = v_class_subject_id
    ) then
        v_d2 := new.score;
    elsif new.assessment_id in (
        select id from public.assessments
         where term = v_term and kind = 'examen'
           and class_subject_id = v_class_subject_id
    ) then
        v_ex := new.score;
    end if;

    if v_d1 is not null and v_d2 is not null and v_ex is not null then
        new.subject_average := round(((v_d1 + v_d2 + 2 * v_ex) / 4.0)::numeric, 2);
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_direct_channel(p_other_profile_id uuid, p_name text DEFAULT NULL::text)
 RETURNS chat_channels
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_me     uuid := public.current_user_profile_id();
    v_tenant uuid := public.current_tenant_id();
    v_a      uuid;
    v_b      uuid;
    v_code   text;
    v_ch     public.chat_channels;
begin
    if v_me is null then
        raise exception 'create_direct_channel: no user profile for the caller (auth.uid() has no user_profiles row)'
            using errcode = '42501';
    end if;
    if v_tenant is null then
        raise exception 'create_direct_channel: caller has no tenant (global admins must act inside a tenant context)'
            using errcode = '42501';
    end if;
    -- T-400: the full STAFF role set (0023 census minus parent/student) —
    -- the workforce employee roles are staff; parents stay read+reply by
    -- design (their path is open_parent_admin_channel, 0067).
    if not public.has_any_role(array[
        'super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher',
        'worker', 'buyer', 'driver', 'warehouse_worker'
    ]) then
        raise exception 'create_direct_channel: only staff may create chat channels (parents are read+reply by design)'
            using errcode = '42501';
    end if;
    if p_other_profile_id is null or p_other_profile_id = v_me then
        raise exception 'create_direct_channel: p_other_profile_id must be a different profile from the caller'
            using errcode = '22023';
    end if;
    -- The other member must be a real profile of the same tenant (or a
    -- global-admin profile). Guards against fabricated member ids.
    if not exists (
        select 1 from public.user_profiles up
         where up.id = p_other_profile_id
           and (up.tenant_id = v_tenant or up.tenant_id is null)
    ) then
        raise exception 'create_direct_channel: other profile not found in the caller''s tenant'
            using errcode = '22023';
    end if;

    v_a := least(v_me, p_other_profile_id);
    v_b := greatest(v_me, p_other_profile_id);
    v_code := 'DM-' || v_a || '-' || v_b;

    insert into public.chat_channels (
        tenant_id, code, name, channel_type, member_ids, created_by, description
    ) values (
        v_tenant, v_code, coalesce(nullif(btrim(p_name), ''), 'Direct'), 'direct',
        array[v_a, v_b], v_me, null
    )
    on conflict (tenant_id, code) do nothing
    returning * into v_ch;

    if v_ch is null then
        -- Already exists (idempotent re-open by either member of the pair).
        select * into v_ch
          from public.chat_channels
         where tenant_id = v_tenant and code = v_code;
    end if;

    if v_ch is null then
        raise exception 'create_direct_channel: channel vanished after upsert'
            using errcode = '22023';
    end if;

    -- Audit the creation (mock parity: chat.channel_create; convention 0014).
    if v_ch.created_by = v_me then
        insert into public.audit_logs (
            tenant_id, action, entity_type, entity_id, actor_id, after_json, note
        ) values (
            v_tenant, 'chat.channel_create', 'chat_channel', v_ch.id, v_me,
            to_jsonb(v_ch), 'create_direct_channel (idempotent RPC)'
        );
    end if;

    return v_ch;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_manual_debt(p_parent_id text, p_student_id text, p_category text, p_label text, p_amount_due numeric, p_due_date date, p_academic_year text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text)
 RETURNS TABLE(installment_id uuid, ledger_entry_id uuid, academic_year_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant      uuid := public.current_tenant_id();
    v_parent      uuid := public.resolve_parent_ref(v_tenant, p_parent_id);
    v_student     uuid := public.resolve_student_ref(v_tenant, p_student_id);
    v_label       text := nullif(btrim(coalesce(p_label, '')), '');
    v_note        text := nullif(btrim(coalesce(p_note, '')), '');
    v_reference   text := nullif(btrim(coalesce(p_reference, '')), '');
    v_year_id     uuid;
    v_ins_id      uuid;
    v_ledger_id   uuid;
    v_entry_no    text;
    v_description text;
    v_account_id  text;
begin
    -- Gate 1 — staff roles (the installments_admin policy's audience).
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: manual debt creation is a staff financial write';
    end if;

    -- Gate 2 — the refs must resolve (the upsert_installment_from_import errors).
    if v_parent is null then
        raise exception 'create_manual_debt: unresolvable parent ref %', p_parent_id;
    end if;
    if v_student is null then
        raise exception 'create_manual_debt: unresolvable student ref %', p_student_id;
    end if;

    -- Gate 3 — the contract guards (fail closed, before any write).
    if v_label is null or length(v_label) < 3 then
        raise exception 'create_manual_debt: the label (the reason) is required (>= 3 chars)';
    end if;
    if p_amount_due is null or p_amount_due <= 0 then
        raise exception 'create_manual_debt: the amount must be strictly positive';
    end if;
    if p_due_date is null then
        raise exception 'create_manual_debt: the due date is required';
    end if;
    if p_category is null or btrim(p_category) = '' then
        raise exception 'create_manual_debt: the category is required';
    end if;

    -- The academic-year stamp — the SAME precedence the import path applies
    -- (0127/0129): explicit code/label match first, then the INV-14 window
    -- resolver on the due date. Frozen at write time (ADR-030 / INV-18b).
    if p_academic_year is not null and nullif(btrim(p_academic_year), '') is not null then
        select ay.id into v_year_id
          from public.academic_years ay
         where ay.tenant_id = v_tenant
           and (ay.code = btrim(p_academic_year) or ay.label = btrim(p_academic_year))
         order by ay.start_date desc
         limit 1;
    end if;
    if v_year_id is null then
        v_year_id := public.resolve_academic_year_id_for_date(p_due_date, v_tenant);
    end if;

    -- The deterministic ledger identity (the led-{ISO}-{rand} convention).
    v_entry_no := 'led-' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
                  || '-' || substr(md5(gen_random_uuid()::text), 1, 8);

    v_description := 'Dette manuelle — ' || v_label
                     || (case when v_note is not null then ' · ' || v_note else '' end)
                     || (case when v_reference is not null then ' · réf. ' || v_reference else '' end);

    -- The charge lands on the student-scoped account when the debt is
    -- student-anchored (the adjust() R1.5 convention), else parent-scoped.
    v_account_id := 'parent:' || v_parent || ':category:' || p_category
                    || ':student:' || v_student;

    -- ------------------------------------------------------------------
    -- Write 1/3 — the INSTALLMENT row (the canonical debt record).
    -- ------------------------------------------------------------------
    v_ins_id := public.gen_uuid();
    insert into public.installments (
        id, tenant_id, parent_id, student_id, category, label,
        tranche_number, amount_due, amount_paid, amount_pending,
        due_date, paid_date, status,
        source_type, source_id,
        created_at, updated_at
    ) values (
        v_ins_id, v_tenant, v_parent, v_student, p_category, v_label,
        null, p_amount_due, 0, 0,
        p_due_date, null, 'unpaid',
        'manual_entry', 'manual-' || v_entry_no,
        now(), now()
    );

    -- ------------------------------------------------------------------
    -- Write 2/3 — the LEDGER charge entry (the billing-wire pattern: every
    -- new obligation is both an installment row and a charge entry).
    -- ------------------------------------------------------------------
    v_ledger_id := public.gen_uuid();
    insert into public.ledger_entries (
        id, tenant_id, entry_number, parent_id, student_id, account_id,
        entry_type, amount, category, description, entry_date,
        source_type, source_id, method, receipt_number, payment_status,
        reverses_id, actor_id, actor_name, at, metadata
    ) values (
        v_ledger_id, v_tenant, v_entry_no, v_parent, v_student, v_account_id,
        'charge', p_amount_due, p_category, v_description,
        (p_due_date::timestamptz at time zone 'UTC'),
        'manual_entry', 'manual-' || v_entry_no, null, null, null,
        null, p_actor_id::text, p_actor_name, now(),
        jsonb_build_object(
            'manual', true,
            'installmentId', v_ins_id,
            'note', v_note,
            'reference', v_reference,
            'reason', v_label,
            'source', 'create_manual_debt'
        )
    );

    -- ------------------------------------------------------------------
    -- Write 3/3 — the AUDIT row (the payment.collect pattern).
    -- ------------------------------------------------------------------
    insert into public.audit_logs (
        id, tenant_id, action, entity_type, entity_id, actor_id, actor_name,
        before_json, after_json, diff, note, created_at
    ) values (
        public.gen_uuid(), v_tenant, 'installment.manual_debt_created', 'installment', v_ins_id,
        p_actor_id, p_actor_name,
        null,
        jsonb_build_object(
            'installmentId', v_ins_id, 'ledgerEntryId', v_ledger_id,
            'parentId', v_parent, 'studentId', v_student,
            'category', p_category, 'label', v_label,
            'amountDue', p_amount_due, 'dueDate', p_due_date,
            'academicYearId', v_year_id, 'reference', v_reference
        ),
        jsonb_build_object(
            'installmentId', v_ins_id, 'ledgerEntryId', v_ledger_id,
            'parentId', v_parent, 'studentId', v_student,
            'category', p_category, 'label', v_label,
            'amountDue', p_amount_due, 'dueDate', p_due_date,
            'academicYearId', v_year_id, 'reference', v_reference
        ),
        'Dette manuelle créée via RPC create_manual_debt (T-466/DEBT-102 — la voie canonique)',
        now()
    );

    return query select v_ins_id, v_ledger_id, v_year_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.deactivate_fcm_tokens(p_user_id uuid, p_platform text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_caller_profile uuid;
    v_is_service_role boolean;
    v_deactivated integer;
BEGIN
    -- Same caller-verification rule as register_fcm_token.
    v_is_service_role := (auth.role() = 'service_role');
    IF NOT v_is_service_role THEN
        SELECT up.id INTO v_caller_profile
          FROM public.user_profiles up
         WHERE up.auth_user_id = auth.uid()
         LIMIT 1;
        IF v_caller_profile IS NULL OR v_caller_profile <> p_user_id THEN
            RAISE EXCEPTION 'deactivate_fcm_tokens: caller does not own user profile %', p_user_id
              USING ERRCODE = '42501';
        END IF;
    END IF;

    UPDATE public.device_tokens
       SET is_active = false,
           updated_at = now()
     WHERE user_id = p_user_id
       AND is_active = true
       AND (p_platform IS NULL OR platform = p_platform);

    GET DIAGNOSTICS v_deactivated = ROW_COUNT;
    RETURN v_deactivated;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_chat_read_by_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_profile uuid := public.current_user_profile_id();
    v_old jsonb := coalesce(old.read_by, '[]'::jsonb);
    v_new jsonb := coalesce(new.read_by, '[]'::jsonb);
begin
    -- Authors keep the full-update path governed by chat_messages_update_own
    -- (edit body, edited_at, deleted_at, attachments …). Nothing changes
    -- for them.
    if v_profile is not null and old.author_id = v_profile then
        return new;
    end if;

    -- Non-author (recipient) path: every column except read_by must be
    -- byte-identical. This is what stops a member from editing or deleting
    -- other people's messages through the new permissive policy.
    if new.tenant_id is distinct from old.tenant_id
       or new.channel_id is distinct from old.channel_id
       or new.author_id is distinct from old.author_id
       or new.body is distinct from old.body
       or new.edited_at is distinct from old.edited_at
       or new.edited_by is distinct from old.edited_by
       or new.deleted_at is distinct from old.deleted_at
       or new.parent_message_id is distinct from old.parent_message_id
       or new.attachments is distinct from old.attachments
       or new.sent_at is distinct from old.sent_at then
        raise exception 'chat_messages: non-author updates may only touch read_by (REALTIME-101)';
    end if;

    -- read_by must GROW by exactly one entry…
    if jsonb_array_length(v_new) <> jsonb_array_length(v_old) + 1 then
        raise exception 'chat_messages: read_by must grow by exactly one entry per update (REALTIME-101)';
    end if;

    -- …without removing or mutating any existing entry…
    if not (v_new @> v_old) then
        raise exception 'chat_messages: existing read_by entries may not be removed or modified (REALTIME-101)';
    end if;

    -- …and the appended entry must be the caller's OWN receipt.
    if not exists (
        select 1
        from jsonb_array_elements(v_new) e
        where e ->> 'user_id' = v_profile::text
          and not (v_old @> jsonb_build_array(e))
    ) then
        raise exception 'chat_messages: the appended read_by entry must belong to the caller (REALTIME-101)';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_decide_proposal(p_proposal_id text, p_decision text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant    uuid;
    v_proposal  public.er_match_proposals;
    v_event_id  uuid;
    v_edge      public.er_identity_edges;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    if p_decision not in ('approve', 'reject') then
        raise exception 'fn_er_decide_proposal: décision invalide (%)', p_decision;
    end if;

    select * into v_proposal
    from public.er_match_proposals
    where id = p_proposal_id and tenant_id = v_tenant
    for update;

    if not found then
        raise exception 'fn_er_decide_proposal: proposition introuvable (%)', p_proposal_id;
    end if;
    if v_proposal.status <> 'proposed' then
        raise exception 'fn_er_decide_proposal: proposition déjà décidée (statut %)', v_proposal.status
            using hint = 'A decided proposal is immutable — the audit trail is the correction path.';
    end if;

    -- 1. The edge: active on approve, negative on reject.
    --    A pre-existing negative edge means the pair was rejected before —
    --    refuse the approval (the review queue never re-proposes it anyway).
    select * into v_edge
    from public.er_identity_edges
    where tenant_id = v_tenant
      and a_observation_key = v_proposal.a_observation_key
      and b_observation_key = v_proposal.b_observation_key;

    if p_decision = 'reject' then
        insert into public.er_identity_edges as e (
            tenant_id, a_observation_key, b_observation_key, confidence, status,
            evidence, created_by
        ) values (
            v_tenant, v_proposal.a_observation_key, v_proposal.b_observation_key,
            v_proposal.confidence, 'negative',
            v_proposal.evidence, p_actor_id
        )
        on conflict (tenant_id, a_observation_key, b_observation_key)
        do update set status = 'negative', severed_at = null, severed_by = null;

        update public.er_match_proposals
        set status = 'rejected', decided_by = p_actor_id,
            decided_by_name = p_actor_name, decided_at = now(), rationale = p_rationale
        where id = p_proposal_id and tenant_id = v_tenant;

        insert into public.er_aggregation_events (
            tenant_id, event_type, run_id, canonical_id, observation_keys,
            actor_id, actor_name, rationale, payload
        ) values (
            v_tenant, 'PROPOSAL_REJECTED', v_proposal.run_id, v_proposal.b_canonical_id,
            array[v_proposal.a_observation_key, v_proposal.b_observation_key],
            p_actor_id, p_actor_name, p_rationale,
            jsonb_build_object('proposalId', p_proposal_id, 'confidence', v_proposal.confidence,
                               'band', v_proposal.band)
        ) returning id into v_event_id;

    else
        if v_edge.status = 'negative' then
            raise exception 'fn_er_decide_proposal: paire déjà rejetée (contrainte négative)'
                using hint = 'Un-reject explicitly via the review surface first.';
        end if;

        insert into public.er_identity_edges as e (
            tenant_id, a_observation_key, b_observation_key, confidence, status,
            evidence, created_by
        ) values (
            v_tenant, v_proposal.a_observation_key, v_proposal.b_observation_key,
            v_proposal.confidence, 'active',
            v_proposal.evidence, p_actor_id
        )
        on conflict (tenant_id, a_observation_key, b_observation_key)
        do update set status = 'active', confidence = excluded.confidence,
                      evidence = excluded.evidence, severed_at = null, severed_by = null;

        update public.er_match_proposals
        set status = 'approved', decided_by = p_actor_id,
            decided_by_name = p_actor_name, decided_at = now(), rationale = p_rationale
        where id = p_proposal_id and tenant_id = v_tenant;

        insert into public.er_aggregation_events (
            tenant_id, event_type, run_id, canonical_id, observation_keys,
            actor_id, actor_name, rationale, payload
        ) values (
            v_tenant, 'PROPOSAL_APPROVED', v_proposal.run_id, v_proposal.b_canonical_id,
            array[v_proposal.a_observation_key, v_proposal.b_observation_key],
            p_actor_id, p_actor_name, p_rationale,
            jsonb_build_object('proposalId', p_proposal_id, 'confidence', v_proposal.confidence,
                               'band', v_proposal.band)
        ) returning id into v_event_id;
    end if;

    -- 2. Audit (the canonical trail).
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.decide_proposal',
        p_entity_type := 'er_match_proposal',
        p_entity_id   := null,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'proposalId', p_proposal_id,
                             'decision', p_decision,
                             'confidence', v_proposal.confidence,
                             'band', v_proposal.band
                         ),
        p_note        := format('ER-PMAE : proposition %s — décision %s (confiance %s).',
                                p_proposal_id, p_decision, v_proposal.confidence)
    );

    return jsonb_build_object(
        'eventId', v_event_id,
        'proposalId', p_proposal_id,
        'status', case when p_decision = 'approve' then 'approved' else 'rejected' end
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_has_aggregation_state(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
begin
    -- T-439 (SEC-115): the caller-tenant guard (read-only surface, same
    -- boundary as the mutators).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    return exists (
        select 1 from public.er_match_proposals
        where tenant_id = v_tenant
          and status <> 'proposed'
    ) or exists (
        select 1 from public.er_identity_edges
        where tenant_id = v_tenant
          and status = 'active'
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_merge_parents(p_target_parent_id uuid, p_source_parent_id uuid, p_proposal_id text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant       uuid;
    v_target       public.parents;
    v_source       public.parents;
    v_event_id     uuid;
    v_students     jsonb := '{}'::jsonb;
    v_payments     jsonb := '{}'::jsonb;
    v_installments jsonb := '{}'::jsonb;
    v_ledger       jsonb := '{}'::jsonb;
    v_row          record;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);
    if p_target_parent_id is null or p_source_parent_id is null
       or p_target_parent_id = p_source_parent_id then
        raise exception 'fn_er_merge_parents: cible et source requis et distincts';
    end if;

    select * into v_target from public.parents
    where id = p_target_parent_id and tenant_id = v_tenant;
    select * into v_source from public.parents
    where id = p_source_parent_id and tenant_id = v_tenant;

    if v_target.id is null or v_source.id is null then
        raise exception 'fn_er_merge_parents: parent introuvable (cible ou source)';
    end if;
    if v_source.deleted_at is not null then
        raise exception 'fn_er_merge_parents: la source est déjà fusionnée/supprimée (deleted_at non nul)'
            using hint = 'Un-merge the prior merge first.';
    end if;

    -- 1. Capture the COMPLETE prior mapping (the restore contract), then
    --    re-point each relationship table (INV-54: re-point, never rewrite).
    for v_row in
        select id from public.students
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_students := v_students || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.students
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.payments
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_payments := v_payments || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.payments
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.installments
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_installments := v_installments || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.installments
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    for v_row in
        select id from public.ledger_entries
        where tenant_id = v_tenant and parent_id = p_source_parent_id
        for update
    loop
        v_ledger := v_ledger || jsonb_build_object(v_row.id::text, p_source_parent_id::text);
    end loop;
    update public.ledger_entries
    set parent_id = p_target_parent_id
    where tenant_id = v_tenant and parent_id = p_source_parent_id;

    -- 2. Soft-delete the merged-away parent (the T-384 convention).
    update public.parents
    set deleted_at = now()
    where id = p_source_parent_id and tenant_id = v_tenant;

    -- 3. The append-only event carrying the COMPLETE prior mapping.
    insert into public.er_aggregation_events (
        tenant_id, event_type, run_id, canonical_id, merged_away_id,
        observation_keys, actor_id, actor_name, rationale, payload
    ) values (
        v_tenant, 'MERGE_EXECUTED', null, p_target_parent_id, p_source_parent_id,
        '{}', p_actor_id, p_actor_name, p_rationale,
        jsonb_build_object(
            'proposalId', p_proposal_id,
            'restoreMapping', jsonb_build_object(
                'students', v_students,
                'payments', v_payments,
                'installments', v_installments,
                'ledger_entries', v_ledger
            )
        )
    ) returning id into v_event_id;

    -- 4. Audit (the canonical trail).
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.merge_parents',
        p_entity_type := 'parent',
        p_entity_id   := p_target_parent_id,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object(
                             'sourceParentId', p_source_parent_id,
                             'sourceParentCode', v_source.parent_code
                         ),
        p_after_json  := jsonb_build_object(
                             'targetParentId', p_target_parent_id,
                             'targetParentCode', v_target.parent_code,
                             'eventId', v_event_id,
                             'rePointed', jsonb_build_object(
                                 'students', (select count(*) from jsonb_object_keys(v_students)),
                                 'payments', (select count(*) from jsonb_object_keys(v_payments)),
                                 'installments', (select count(*) from jsonb_object_keys(v_installments)),
                                 'ledger_entries', (select count(*) from jsonb_object_keys(v_ledger))
                             )
                         ),
        p_note        := format('ER-PMAE : fusion réversible du parent %s dans %s (%s) — mappage complet enregistré (événement %s).',
                                v_source.parent_code, v_target.parent_code,
                                coalesce(p_rationale, 'décision humaine'), v_event_id)
    );

    return jsonb_build_object(
        'eventId', v_event_id,
        'targetParentId', p_target_parent_id,
        'sourceParentId', p_source_parent_id,
        'rePointed', jsonb_build_object(
            'students', v_students,
            'payments', v_payments,
            'installments', v_installments,
            'ledger_entries', v_ledger
        )
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_er_unmerge_parents(p_event_id uuid, p_actor_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text, p_rationale text DEFAULT NULL::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant      uuid;
    v_event       public.er_aggregation_events;
    v_restore     jsonb;
    v_row_id      uuid;
    v_prev_parent uuid;
    v_counts      jsonb;
    v_undone_id   uuid;
begin
    -- 0. Tenant + guards (T-439/SEC-115: the 0128 caller-tenant-mismatch
    --    guard — the experimental flag was never an authorization boundary,
    --    and SECURITY DEFINER bypasses the er_* RLS by construction).
    v_tenant := public.fn_er_resolve_tenant(p_tenant_id);

    select * into v_event
    from public.er_aggregation_events
    where id = p_event_id and tenant_id = v_tenant and event_type = 'MERGE_EXECUTED';

    if v_event.id is null then
        raise exception 'fn_er_unmerge_parents: événement de fusion introuvable (%)', p_event_id;
    end if;

    -- One unmerge per merge (idempotence of the reversal).
    if exists (
        select 1 from public.er_aggregation_events
        where tenant_id = v_tenant and event_type = 'MERGE_UNDONE'
          and payload->>'reversesEventId' = p_event_id::text
    ) then
        raise exception 'fn_er_unmerge_parents: cette fusion est déjà annulée';
    end if;

    v_restore := v_event.payload->'restoreMapping';

    -- 1. Replay the prior mapping (only rows that STILL point at the target
    --    from this merge — a row re-parented since is left alone, honestly).
    --    0131 FIX: a direct jsonb→uuid cast raises 42846, and value::text
    --    keeps the JSON quotes — the unquoted extraction is `#>> '{}'`
    --    (the KEY is already unquoted text).
    if v_restore->'students' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'students')
        loop
            update public.students
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'payments' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'payments')
        loop
            update public.payments
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'installments' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'installments')
        loop
            update public.installments
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;
    if v_restore->'ledger_entries' is not null then
        for v_row_id, v_prev_parent in
            select key::uuid, (value #>> '{}')::uuid
            from jsonb_each(v_restore->'ledger_entries')
        loop
            update public.ledger_entries
            set parent_id = v_prev_parent
            where id = v_row_id and tenant_id = v_tenant
              and parent_id = v_event.canonical_id;
        end loop;
    end if;

    -- 2. Restore the merged-away parent (un-soft-delete).
    update public.parents
    set deleted_at = null
    where id = v_event.merged_away_id and tenant_id = v_tenant;

    -- 3. Sever the identity edges tied to the merged-away canonical entity.
    update public.er_identity_edges
    set status = 'severed', severed_at = now(), severed_by = p_actor_id
    where tenant_id = v_tenant and status = 'active'
      and (a_observation_key = 'canonical:' || v_event.merged_away_id::text
           or b_observation_key = 'canonical:' || v_event.merged_away_id::text);

    -- 4. The MERGE_UNDONE event (referencing the reversed merge).
    insert into public.er_aggregation_events (
        tenant_id, event_type, run_id, canonical_id, merged_away_id,
        observation_keys, actor_id, actor_name, rationale, payload
    ) values (
        v_tenant, 'MERGE_UNDONE', v_event.run_id, v_event.canonical_id, v_event.merged_away_id,
        v_event.observation_keys, p_actor_id, p_actor_name, p_rationale,
        jsonb_build_object('reversesEventId', p_event_id::text)
    ) returning id into v_undone_id;

    -- 5. Audit.
    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'er.unmerge_parents',
        p_entity_type := 'parent',
        p_entity_id   := v_event.merged_away_id,
        p_actor_id    := p_actor_id,
        p_actor_name  := p_actor_name,
        p_before_json := jsonb_build_object('mergeEventId', p_event_id),
        p_after_json  := jsonb_build_object('undoneEventId', v_undone_id,
                                            'restoredParentId', v_event.merged_away_id),
        p_note        := format('ER-PMAE : annulation de la fusion %s — mappage restauré, parent %s rétabli.',
                                p_event_id, v_event.merged_away_id)
    );

    select jsonb_build_object(
        'students', (select count(*) from jsonb_object_keys(coalesce(v_restore->'students', '{}'::jsonb))),
        'payments', (select count(*) from jsonb_object_keys(coalesce(v_restore->'payments', '{}'::jsonb))),
        'installments', (select count(*) from jsonb_object_keys(coalesce(v_restore->'installments', '{}'::jsonb))),
        'ledger_entries', (select count(*) from jsonb_object_keys(coalesce(v_restore->'ledger_entries', '{}'::jsonb)))
    ) into v_counts;

    return jsonb_build_object(
        'eventId', v_undone_id,
        'restoredParentId', v_event.merged_away_id,
        'restored', v_counts
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_timetable_publish(p_version_id uuid, p_actor_profile_id uuid DEFAULT NULL::uuid, p_actor_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant       uuid;
    v_version      public.timetable_versions%ROWTYPE;
    v_archived_id  uuid;
begin
    -- Caller verification (the 0055/0096 hardening pattern): fail closed.
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        return jsonb_build_object('ok', false, 'reason', 'no_tenant',
                                  'message', 'Aucun tenant résolu pour l''appelant.');
    end if;
    if not public.has_any_role(ARRAY['super_admin','support_staff']) then
        return jsonb_build_object('ok', false, 'reason', 'forbidden',
                                  'message', 'Seuls les administrateurs peuvent publier un emploi du temps.');
    end if;

    select * into v_version
    from public.timetable_versions
    where id = p_version_id and tenant_id = v_tenant
    for update;
    if not found then
        return jsonb_build_object('ok', false, 'reason', 'not_found',
                                  'message', 'Version d''emploi du temps introuvable.');
    end if;
    if v_version.status <> 'approved' then
        return jsonb_build_object('ok', false, 'reason', 'invalid_status',
                                  'message', 'Seule une version approuvée peut être publiée (statut actuel : '
                                             || v_version.status || ').');
    end if;

    -- Archive the currently published version (atomic swap; the partial
    -- unique index timetable_versions_one_published is the backstop).
    update public.timetable_versions
    set status = 'archived', updated_at = now()
    where tenant_id = v_tenant
      and academic_year_id = v_version.academic_year_id
      and status = 'published'
    returning id into v_archived_id;

    update public.timetable_versions
    set status = 'published',
        published_by = p_actor_profile_id,
        published_at = now(),
        updated_at = now()
    where id = p_version_id;

    perform public.write_audit_log(
        p_tenant_id   := v_tenant,
        p_action      := 'timetable.version_publish',
        p_entity_type := 'timetable_version',
        p_entity_id   := p_version_id,
        p_actor_id    := p_actor_profile_id,
        p_actor_name  := p_actor_name,
        p_after_json  := jsonb_build_object(
                             'versionNumber', v_version.version_number,
                             'archivedVersionId', v_archived_id
                         ),
        p_note        := format('Emploi du temps version %s publié pour l''année %s.',
                                v_version.version_number, v_version.academic_year_id)
    );

    return jsonb_build_object(
        'ok', true,
        'publishedVersionId', p_version_id,
        'archivedVersionId', v_archived_id
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_activation_code(p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_code text;
    v_attempts integer := 0;
begin
    loop
        v_code := lpad((floor(random() * 9000000 + 1000000))::text, 7, '0');
        v_attempts := v_attempts + 1;
        if not exists (
            select 1 from public.activation_codes
             where tenant_id = p_tenant_id
               and code = v_code
               and bound_to_auth_user_id is null
        ) then
            return v_code;
        end if;
        exit when v_attempts > 100;
    end loop;
    raise exception 'Could not generate unique activation code after 100 attempts';
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_receipt_numbers(p_tenant_id uuid, p_count integer)
 RETURNS TABLE(receipt_number text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_year INT := EXTRACT(YEAR FROM NOW());
  v_seq INT;
  v_i INT;
BEGIN
  IF p_count IS NULL OR p_count <= 0 THEN
    RETURN;
  END IF;

  -- SEC-111 pattern: the function is SECURITY DEFINER (it must read the
  -- tenant's payments regardless of the caller's RLS). Verify the caller.
  IF coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
     AND NOT public.is_global_admin()
     AND p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
      RAISE EXCEPTION 'generate_receipt_numbers: p_tenant_id does not match the authenticated caller''s tenant (SEC-111 pattern, T-015)';
  END IF;

  -- Serialize concurrent batch allocations for the same tenant so two
  -- importers never compute overlapping ranges. Transaction-scoped: released
  -- automatically at commit/rollback.
  PERFORM pg_advisory_xact_lock(hashtext('el-imtiyaz:receipt_numbers:' || p_tenant_id::text));

  SELECT COALESCE(MAX(CAST(SUBSTRING(pay.receipt_number FROM '\d{6}$') AS INT)), 0) INTO v_seq
  FROM payments pay
  WHERE pay.tenant_id = p_tenant_id AND pay.receipt_number LIKE 'REC-' || v_year || '-%';

  FOR v_i IN 1 .. p_count LOOP
    receipt_number := 'REC-' || v_year || '-' || LPAD((v_seq + v_i)::TEXT, 6, '0');
    RETURN NEXT;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_signed_url(p_bucket_id text, p_object_path text, p_expires_seconds integer DEFAULT 300)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_url text;
    v_tenant_id uuid := public.current_tenant_id();
begin
    -- Validate tenant isolation: object path must start with tenant_id
    if not p_object_path like v_tenant_id::text || '/%' then
        raise exception 'Access denied: object does not belong to caller''s tenant';
    end if;

    -- Use Supabase storage function to generate signed URL
    -- (This is a placeholder — actual signed URL generation happens via
    -- the Supabase JS client or Edge Function; this SQL function is for
    -- server-side use cases where a function needs to return a URL.)
    select 'signed-url-placeholder' into v_url;

    return v_url;
end;
$function$

CREATE OR REPLACE FUNCTION public.open_parent_admin_channel(p_name text DEFAULT NULL::text)
 RETURNS chat_channels
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_me     uuid := public.current_user_profile_id();
    v_tenant uuid := public.current_tenant_id();
    v_admin  uuid;
    v_a      uuid;
    v_b      uuid;
    v_code   text;
    v_ch     public.chat_channels;
begin
    if v_me is null then
        raise exception 'open_parent_admin_channel: no user profile for the caller (auth.uid() has no user_profiles row)'
            using errcode = '42501';
    end if;
    if v_tenant is null then
        raise exception 'open_parent_admin_channel: caller has no tenant'
            using errcode = '42501';
    end if;

    -- T-413 / STUDENT-104: the user side of the messenger is for PARENT and
    -- STUDENT accounts (an approved student is a system user who may reach
    -- the Administration — ADR-012's user↔admin scope). Staff keep using
    -- create_direct_channel (0061).
    if not exists (
        select 1
          from public.role_assignments ra
          join public.roles r on r.id = ra.role_id
         where ra.user_profile_id = v_me
           and (ra.tenant_id = v_tenant or ra.tenant_id is null)
           and ra.revoked_at is null
           and r.code in ('parent', 'student')
    ) then
        raise exception 'open_parent_admin_channel: only parent or student accounts may open the administration channel'
            using errcode = '42501';
    end if;
    if public.has_any_role(array['super_admin', 'manager', 'support_staff', 'financial_officer', 'teacher']) then
        raise exception 'open_parent_admin_channel: staff members must use create_direct_channel (0061)'
            using errcode = '42501';
    end if;

    -- Resolve the Administrator: the tenant's oldest ACTIVE super_admin,
    -- falling back to the oldest ACTIVE support_staff.
    select up.id into v_admin
      from public.user_profiles up
      join public.role_assignments ra on ra.user_profile_id = up.id and ra.revoked_at is null
      join public.roles r on r.id = ra.role_id
     where r.code = 'super_admin'
       and (ra.tenant_id = v_tenant or ra.tenant_id is null)
       and up.status = 'active'
     order by up.created_at
     limit 1;

    if v_admin is null then
        select up.id into v_admin
          from public.user_profiles up
          join public.role_assignments ra on ra.user_profile_id = up.id and ra.revoked_at is null
          join public.roles r on r.id = ra.role_id
         where r.code = 'support_staff'
           and (ra.tenant_id = v_tenant or ra.tenant_id is null)
           and up.status = 'active'
         order by up.created_at
         limit 1;
    end if;

    if v_admin is null then
        raise exception 'open_parent_admin_channel: no active administrator account found for this tenant (create the super_admin account first)'
            using errcode = '02000';
    end if;
    if v_admin = v_me then
        raise exception 'open_parent_admin_channel: the administrator cannot open a channel with themselves'
            using errcode = '22023';
    end if;

    -- Deterministic idempotent DM code — the SAME pair algorithm as 0061's
    -- create_direct_channel, so the channel a user opens here is the very
    -- channel the staff side's openParentChannel/create_direct_channel
    -- would resolve to for the same pair (one conversation per pair).
    v_a := least(v_me, v_admin);
    v_b := greatest(v_me, v_admin);
    v_code := 'DM-' || v_a || '-' || v_b;

    insert into public.chat_channels (
        tenant_id, code, name, channel_type, member_ids, created_by, description
    ) values (
        v_tenant, v_code,
        coalesce(nullif(btrim(p_name), ''), 'Administration'),
        'direct', array[v_a, v_b], v_me,
        'User (parent/student) to administration channel (0067, ADR-012; student eligibility added by 0116, T-413)'
    )
    on conflict (tenant_id, code) do nothing
    returning * into v_ch;

    if v_ch is null then
        -- Already exists (idempotent re-open by either member of the pair).
        select * into v_ch
          from public.chat_channels
         where tenant_id = v_tenant and code = v_code;
    end if;

    if v_ch is null then
        raise exception 'open_parent_admin_channel: channel vanished after upsert'
            using errcode = '22023';
    end if;

    -- Audit the creation (0014 convention; mirrors 0061's chat.channel_create).
    if v_ch.created_by = v_me then
        insert into public.audit_logs (
            tenant_id, action, entity_type, entity_id, actor_id, after_json, note
        ) values (
            v_tenant, 'chat.parent_admin_channel_open', 'chat_channel', v_ch.id, v_me,
            to_jsonb(v_ch), 'open_parent_admin_channel (idempotent RPC, migration 0067 / ADR-012; student eligibility: 0116, T-413)'
        );
    end if;

    return v_ch;
end;
$function$

CREATE OR REPLACE FUNCTION public.prevent_self_releve_entry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_personnel_user_id uuid;
begin
    -- T-482 / ADR-034: auto rows are recorded by the canonical
    -- record_auto_releve_entry RPC — the system side effect of the caller's
    -- OWN classroom operation (§09.06), where recorded_by == the teacher's
    -- user id BY DESIGN. The §09.05 ban below governs manual rows only.
    if new.entry_source = 'auto' then
        return new;
    end if;

    select user_id into v_personnel_user_id from public.personnel where id = new.personnel_id;

    if v_personnel_user_id is not null and v_personnel_user_id = new.recorded_by then
        raise exception 'Plan §09.05 violation: a teacher cannot record their own Releve entry. Use a separate administrator.';
    end if;

    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.purge_student_parent_domain(p_confirm_phrase text, p_dry_run boolean DEFAULT true, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant         uuid;
    v_counts         jsonb := '{}'::jsonb;
    v_total          bigint := 0;
    v_n              bigint;
    v_parent_ids     uuid[];
    v_student_ids    uuid[];
    v_auth_ids       uuid[];
    v_profile_ids    uuid[];
    v_channel_ids    uuid[];
    v_audit_id       uuid;
    v_other_queue    bigint;
begin
    -- Gate 1 — super_admin OR a DB-superuser console session (ADR-027).
    if not (
        public.has_role('super_admin')
        or exists (select 1 from pg_roles where rolname = session_user and rolsuper)
    ) then
        return jsonb_build_object('ok', false, 'code', 'forbidden');
    end if;

    -- Gate 2 — tenant resolution (explicit param → caller context → fail
    -- closed; NEVER a null-tenant match-everything).
    v_tenant := coalesce(p_tenant_id, public.current_tenant_id());
    if v_tenant is null then
        return jsonb_build_object('ok', false, 'code', 'tenant_unresolved');
    end if;
    if not exists (select 1 from public.tenants where id = v_tenant) then
        return jsonb_build_object('ok', false, 'code', 'invalid_tenant');
    end if;

    -- Gate 3 — the typed phrase, execute mode only (dry-run deletes nothing).
    if not p_dry_run and coalesce(btrim(p_confirm_phrase), '') <> 'PURGER' then
        return jsonb_build_object('ok', false, 'code', 'confirmation_required');
    end if;

    -- ------------------------------------------------------------------
    -- Target collection — EVERY set is resolved BEFORE any delete so the
    -- dry-run preview and the execution see the SAME blast radius.
    -- ------------------------------------------------------------------
    select coalesce(array_agg(p.id), '{}') into v_parent_ids
      from public.parents p where p.tenant_id = v_tenant;

    select coalesce(array_agg(s.id), '{}') into v_student_ids
      from public.students s where s.tenant_id = v_tenant;

    -- The portal accounts of the domain — parents' + students' auth users,
    -- EXCLUDING any account that holds a staff role (the staff guard).
    select coalesce(array_agg(distinct au), '{}') into v_auth_ids
      from (
            select p.auth_user_id as au from public.parents p
             where p.tenant_id = v_tenant and p.auth_user_id is not null
            union
            select s.auth_user_id from public.students s
             where s.tenant_id = v_tenant and s.auth_user_id is not null
           ) ids(au)
     where not exists (
            select 1
              from public.user_profiles up
              join public.role_assignments ra on ra.user_profile_id = up.id
                                              and ra.revoked_at is null
              join public.roles r on r.id = ra.role_id and r.is_staff_role
             where up.auth_user_id = ids.au
           );

    select coalesce(array_agg(up.id), '{}') into v_profile_ids
      from public.user_profiles up
     where up.auth_user_id = any(v_auth_ids);

    -- Parent-member chat channels (ADR-012 parent↔admin direct channels;
    -- member_ids is a NATIVE uuid[] of user_profiles.id (0010) → the
    -- array-overlap operator &&, NOT a jsonb operator).
    select coalesce(array_agg(c.id), '{}') into v_channel_ids
      from public.chat_channels c
     where c.tenant_id = v_tenant
       and c.member_ids && v_profile_ids;

    -- The per-family helper: same predicate for the count (dry-run) and
    -- the delete (execute) — the preview can never drift from the blast.
    -- ------------------------------------------------------------------
    -- A. The financial closure (children before parents, RESTRICT-safe)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.payment_allocations t
         where t.tenant_id = v_tenant;
    else
        delete from public.payment_allocations t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('payment_allocations', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.payments t where t.tenant_id = v_tenant;
    else
        delete from public.payments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('payments', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.installments t where t.tenant_id = v_tenant;
    else
        delete from public.installments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('installments', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.invoices t where t.tenant_id = v_tenant;
    else
        delete from public.invoices t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('invoices', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.ledger_entries t where t.tenant_id = v_tenant;
    else
        delete from public.ledger_entries t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('ledger_entries', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.account_adjustments t where t.tenant_id = v_tenant;
    else
        delete from public.account_adjustments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('account_adjustments', v_n); v_total := v_total + v_n;

    -- receipts: in the file chain (0007) but ABSENT live (§57c) — the
    -- existence guard keeps the branch dead where the table does not exist
    -- (PL/pgSQL compiles lazily; the dead branch never parses).
    if exists (select 1 from information_schema.tables
                where table_schema = 'public' and table_name = 'receipts') then
        if p_dry_run then
            select count(*) into v_n from public.receipts t where t.tenant_id = v_tenant;
        else
            delete from public.receipts t where t.tenant_id = v_tenant;
            get diagnostics v_n = row_count;
        end if;
        v_counts := v_counts || jsonb_build_object('receipts', v_n); v_total := v_total + v_n;
    end if;

    if p_dry_run then
        select count(*) into v_n from public.discount_applications t where t.tenant_id = v_tenant;
    else
        delete from public.discount_applications t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('discount_applications', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.service_enrollments t where t.tenant_id = v_tenant;
    else
        delete from public.service_enrollments t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('service_enrollments', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- B. The academic student data (incl. the 0004 no-FK soft references)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.grades t where t.tenant_id = v_tenant;
    else
        delete from public.grades t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('grades', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.attendance_records t where t.tenant_id = v_tenant;
    else
        delete from public.attendance_records t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('attendance_records', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.academic_history t where t.tenant_id = v_tenant;
    else
        delete from public.academic_history t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('academic_history', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.student_academic_histories t where t.tenant_id = v_tenant;
    else
        delete from public.student_academic_histories t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('student_academic_histories', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.student_documents t where t.tenant_id = v_tenant;
    else
        delete from public.student_documents t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('student_documents', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- C. The CRM core (links before principals; parents LAST)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.activation_codes t where t.tenant_id = v_tenant;
    else
        delete from public.activation_codes t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('activation_codes', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.parent_student_links t where t.tenant_id = v_tenant;
    else
        delete from public.parent_student_links t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('parent_student_links', v_n); v_total := v_total + v_n;

    -- approval requests LINKED to purged rows, PLUS any request keyed to
    -- an auth account the purge is deleting (PURGE-502: the GoTrue trigger
    -- creates requests keyed by auth_user_id with target_parent_id NULL,
    -- and 0044 resolves them without ever linking a target — after the
    -- bind, the parents row claims the same auth_user_id; leaving the
    -- request behind would orphan it against the deleted account). A
    -- pending signup whose account is NOT claimed by any parent/student
    -- row keeps BOTH its account and its request (ADR-027's pre-parent
    -- boundary preserved — v_auth_ids only contains claimed accounts).
    if p_dry_run then
        select count(*) into v_n from public.account_approval_requests t
         where t.tenant_id = v_tenant
           and (t.target_parent_id = any(v_parent_ids)
                or t.target_student_id = any(v_student_ids)
                or t.auth_user_id = any(v_auth_ids));
    else
        delete from public.account_approval_requests t
         where t.tenant_id = v_tenant
           and (t.target_parent_id = any(v_parent_ids)
                or t.target_student_id = any(v_student_ids)
                or t.auth_user_id = any(v_auth_ids));
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('account_approval_requests', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.students t where t.tenant_id = v_tenant;
    else
        delete from public.students t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('students', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.parents t where t.tenant_id = v_tenant;
    else
        delete from public.parents t where t.tenant_id = v_tenant;
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('parents', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- D. The portal/auth closure (messages before channels; auth.users
    --    LAST; the staff guard already excluded staff accounts above)
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.chat_messages t
         where t.tenant_id = v_tenant and t.channel_id = any(v_channel_ids);
    else
        delete from public.chat_messages t
         where t.tenant_id = v_tenant and t.channel_id = any(v_channel_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('chat_messages', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.chat_channels t
         where t.tenant_id = v_tenant and t.id = any(v_channel_ids);
    else
        delete from public.chat_channels t
         where t.tenant_id = v_tenant and t.id = any(v_channel_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('chat_channels', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.notifications t
         where t.tenant_id = v_tenant
           and (t.target_user_id = any(v_auth_ids)
                or (t.link_entity_type = 'parent' and t.link_entity_id = any(v_parent_ids))
                or (t.link_entity_type = 'student' and t.link_entity_id = any(v_student_ids)));
    else
        delete from public.notifications t
         where t.tenant_id = v_tenant
           and (t.target_user_id = any(v_auth_ids)
                or (t.link_entity_type = 'parent' and t.link_entity_id = any(v_parent_ids))
                or (t.link_entity_type = 'student' and t.link_entity_id = any(v_student_ids)));
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('notifications', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.calendar_events t
         where t.tenant_id = v_tenant
           and t.target_entity_type in ('parent', 'student')
           and (t.target_entity_id = any(v_parent_ids)
                or t.target_entity_id = any(v_student_ids));
    else
        delete from public.calendar_events t
         where t.tenant_id = v_tenant
           and t.target_entity_type in ('parent', 'student')
           and (t.target_entity_id = any(v_parent_ids)
                or t.target_entity_id = any(v_student_ids));
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('calendar_events', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.notification_preferences t
         where t.tenant_id = v_tenant and t.user_profile_id = any(v_profile_ids);
    else
        delete from public.notification_preferences t
         where t.tenant_id = v_tenant and t.user_profile_id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('notification_preferences', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.device_tokens t
         where t.user_id = any(v_auth_ids);
    else
        delete from public.device_tokens t where t.user_id = any(v_auth_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('device_tokens', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.sessions t
         where t.user_profile_id = any(v_profile_ids);
    else
        delete from public.sessions t where t.user_profile_id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('sessions', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.role_assignments t
         where t.user_profile_id = any(v_profile_ids);
    else
        delete from public.role_assignments t where t.user_profile_id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('role_assignments', v_n); v_total := v_total + v_n;

    if p_dry_run then
        select count(*) into v_n from public.user_profiles t
         where t.id = any(v_profile_ids);
    else
        delete from public.user_profiles t where t.id = any(v_profile_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('user_profiles', v_n); v_total := v_total + v_n;

    -- auth.users LAST (the GoTrue accounts; SECURITY DEFINER runs as the
    -- owner — postgres — which the live sandbox proves has the grant).
    if p_dry_run then
        select count(*) into v_n from auth.users t where t.id = any(v_auth_ids);
    else
        delete from auth.users t where t.id = any(v_auth_ids);
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('auth_users', v_n); v_total := v_total + v_n;

    -- ------------------------------------------------------------------
    -- E. The sync staging — ONLY this tenant's five domain entities
    --    (PURGE-501: the queue's idempotent upserts would resurrect every
    --    purged row on the next drain). Everything else in the queue, and
    --    the sync RPCs themselves, are untouched.
    -- ------------------------------------------------------------------
    if p_dry_run then
        select count(*) into v_n from public.sync_queue t
         where t.tenant_id = v_tenant
           and t.entity in ('parent', 'student', 'payment', 'installment', 'ledger_entry');
    else
        delete from public.sync_queue t
         where t.tenant_id = v_tenant
           and t.entity in ('parent', 'student', 'payment', 'installment', 'ledger_entry');
        get diagnostics v_n = row_count;
    end if;
    v_counts := v_counts || jsonb_build_object('sync_queue_domain', v_n); v_total := v_total + v_n;

    -- The non-interference evidence, returned with every call: what the
    -- purge left alone in the queue.
    select count(*) into v_other_queue from public.sync_queue t
     where t.tenant_id = v_tenant
       and t.entity not in ('parent', 'student', 'payment', 'installment', 'ledger_entry');

    -- ------------------------------------------------------------------
    -- The audit entry (append-only journal — execute mode only; dry-run
    -- changed nothing and writes nothing). counts ride p_after_json.
    -- ------------------------------------------------------------------
    if not p_dry_run then
        v_audit_id := public.write_audit_log(
            p_tenant_id   => v_tenant,
            p_action      => 'system.purge_student_parent_domain',
            p_entity_type => 'system',
            p_entity_id   => null,
            p_actor_id    => null,
            p_actor_name  => coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'email', session_user),
            p_after_json  => v_counts || jsonb_build_object('total', v_total),
            p_note        => 'T-416 (issue #12): the student/parent domain reset — '
                             || v_total || ' rows across ' || (select count(*) from jsonb_object_keys(v_counts)) || ' families; '
                             || 'backup/sync-infrastructure/audit-journal/academic-catalog untouched per ADR-027.'
        );
    end if;

    return jsonb_build_object(
        'ok', true,
        'mode', case when p_dry_run then 'dry_run' else 'executed' end,
        'tenant_id', v_tenant,
        'counts', v_counts,
        'total', v_total,
        'preserved', jsonb_build_object(
            'backup_archives', 'untouched',
            'sync_queue_other', v_other_queue,
            'audit_logs', 'append_only',
            'academic_catalog', 'untouched',
            'workforce_operations', 'untouched'
        ),
        'audit_entry_id', v_audit_id
    );
end;
$function$

CREATE OR REPLACE FUNCTION public.read_dashboard_debt_aging(p_academic_year text, p_as_of date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
    v_tenant uuid;
    v_year_start int;
    v_debt_from date;
    v_debt_to date;
    v_as_of date := coalesce(p_as_of, current_date);
    v_result jsonb;
begin
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: debt aging is a staff surface';
    end if;
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    v_year_start := public.academic_year_start(p_academic_year);
    if v_year_start is not null then
        v_debt_from := make_date(v_year_start, 9, 1);
        v_debt_to := make_date(v_year_start + 1, 9, 1);
    end if;

    with aging as (
        select i.parent_id,
               greatest(0, i.amount_due - i.amount_paid - i.amount_pending) as remaining,
               extract(days from ((v_as_of::timestamptz) - ((i.due_date::text || 'T00:00:00Z')::timestamptz)))::int as days_overdue
          from public.installments i
         where i.tenant_id = v_tenant
           and i.status <> 'paid'
           and greatest(0, i.amount_due - i.amount_paid - i.amount_pending) > 0
           and i.due_date < v_as_of
           and (v_debt_from is null or (i.due_date >= v_debt_from and i.due_date < v_debt_to))
    ),
    bucketed as (
        select parent_id, remaining,
               case when days_overdue <= 30 then '0_30'
                    when days_overdue <= 60 then '31_60'
                    when days_overdue <= 90 then '61_90'
                    when days_overdue <= 180 then '91_180'
                    else '180_plus' end as bucket
          from aging
    )
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'bucket', b.bucket,
                'amount', b.amount,
                'debtorCount', b.debtor_count
            )
            order by b.sort_key
        ),
        '[]'::jsonb
    )
      into v_result
      from (
        select bucket,
               sum(remaining) as amount,
               count(distinct parent_id) as debtor_count
          from bucketed
         group by bucket
      ) b
      join (values ('0_30', 1), ('31_60', 2), ('61_90', 3), ('91_180', 4), ('180_plus', 5)) as k(bucket, sort_key)
        on k.bucket = b.bucket;

    -- Empty buckets are honest zeros (the client renders every bucket row).
    if v_result is null then
        v_result := '[]'::jsonb;
    end if;

    return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.read_dashboard_kpis(p_academic_year text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_as_of date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
    v_tenant uuid;
    v_year_start int;
    v_debt_from date;
    v_debt_to date;
    v_rev_from timestamptz;
    v_rev_to timestamptz;
    v_as_of date := coalesce(p_as_of, current_date);
    v_monthly_revenue numeric := 0;
    v_outstanding numeric := 0;
    v_overdue_count bigint := 0;
    v_overdue_amount numeric := 0;
    v_att_present bigint := 0;
    v_att_total bigint := 0;
    v_result jsonb;
begin
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: dashboard KPIs are a staff surface';
    end if;
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    -- The revenue window: the explicit range, else the current UTC month
    -- (the client's monthStart/monthEnd convention — UTC midnight bounds).
    if p_from is not null and p_to is not null then
        v_rev_from := (p_from::text || 'T00:00:00Z')::timestamptz;
        v_rev_to := (p_to::text || 'T00:00:00Z')::timestamptz;
    else
        v_rev_from := date_trunc('month', now() at time zone 'UTC') at time zone 'UTC';
        v_rev_to := (date_trunc('month', now() at time zone 'UTC') + interval '1 month') at time zone 'UTC';
    end if;

    -- The debt family's billing window (T-353): Sept 1 of the parsed start
    -- year → Sept 1 next. An unparseable year code = NO window (the client's
    -- honest "cannot scope" behavior — every unpaid row considered).
    v_year_start := public.academic_year_start(p_academic_year);
    if v_year_start is not null then
        v_debt_from := make_date(v_year_start, 9, 1);
        v_debt_to := make_date(v_year_start + 1, 9, 1);
    end if;

    -- monthlyRevenue: Σ paid payments collected in [from, to) — UTC
    -- midnight bounds, exclusive end (the house convention).
    select coalesce(sum(pay.amount), 0)
      into v_monthly_revenue
      from public.payments pay
     where pay.tenant_id = v_tenant
       and pay.status = 'paid'
       and pay.collected_at >= v_rev_from
       and pay.collected_at < v_rev_to;

    -- outstandingDebt (INV-4): Σ max(0, due − paid − pending) over unpaid
    -- installments in the billing window — the charges are never summed
    -- alone (the §15 installment basis).
    select coalesce(sum(greatest(0, i.amount_due - i.amount_paid - i.amount_pending)), 0)
      into v_outstanding
      from public.installments i
     where i.tenant_id = v_tenant
       and i.status <> 'paid'
       and (v_debt_from is null or (i.due_date >= v_debt_from and i.due_date < v_debt_to));

    -- The dynamic-overdue family (DATA-045): status ≠ 'paid' AND strictly
    -- past due at the as-of day AND a REAL remaining balance. Never the
    -- `status = 'overdue'` string; never future tranches.
    select count(*) filter (where i.due_date < v_as_of),
           coalesce(sum(greatest(0, i.amount_due - i.amount_paid - i.amount_pending))
                     filter (where i.due_date < v_as_of), 0)
      into v_overdue_count, v_overdue_amount
      from public.installments i
     where i.tenant_id = v_tenant
       and i.status <> 'paid'
       and greatest(0, i.amount_due - i.amount_paid - i.amount_pending) > 0
       and (v_debt_from is null or (i.due_date >= v_debt_from and i.due_date < v_debt_to));

    -- attendanceRateToday: present+late / total over the as-of day's records
    -- (the ratio is rounded CLIENT-side with the existing toFixed(2) — zero
    -- rounding drift between the paths).
    select count(*) filter (where r.status in ('present', 'late')),
           count(*)
      into v_att_present, v_att_total
      from public.attendance_records r
     where r.tenant_id = v_tenant
       and r.date = v_as_of;

    select jsonb_build_object(
        'totalStudents', (select count(*) from public.students s
                           where s.tenant_id = v_tenant and s.deleted_at is null),
        'totalParents', (select count(*) from public.parents p
                           where p.tenant_id = v_tenant and p.deleted_at is null),
        'totalStaff', (select count(*) from public.personnel per
                        where per.tenant_id = v_tenant and per.deleted_at is null),
        'monthlyRevenue', v_monthly_revenue,
        'outstandingDebt', v_outstanding,
        'overdueAlerts', v_overdue_count,
        'overdueAmount', v_overdue_amount,
        'pendingExpenses', (select count(*) from public.expense_tickets e
                             where e.tenant_id = v_tenant
                               and e.status in ('draft', 'pending_approval', 'submitted')),
        'attendancePresent', v_att_present,
        'attendanceTotal', v_att_total,
        'asOf', to_char(v_as_of, 'YYYY-MM-DD')
    ) into v_result;

    return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.read_dashboard_revenue_by_month(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
declare
    v_tenant uuid;
    v_result jsonb;
begin
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: dashboard aggregates are a staff surface';
    end if;
    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    with bounds as (
        select (p_from::text || 'T00:00:00Z')::timestamptz as from_ts,
               (p_to::text || 'T00:00:00Z')::timestamptz as to_ts
    ),
    series as (
        select m
          from generate_series(
              date_trunc('month', (select from_ts at time zone 'UTC' from bounds)),
              (select to_ts at time zone 'UTC' from bounds) - interval '1 month',
              interval '1 month'
          ) as m
         limit 24
    ),
    monthly as (
        select to_char(pay.collected_at at time zone 'UTC', 'YYYY-MM') as ym,
               coalesce(sum(pay.amount), 0) as amount
          from public.payments pay, bounds b
         where pay.tenant_id = v_tenant
           and pay.status = 'paid'
           and pay.collected_at >= b.from_ts
           and pay.collected_at < b.to_ts
         group by 1
    )
    select coalesce(
        jsonb_agg(
            jsonb_build_object(
                'year', extract(year from s.m at time zone 'UTC')::int,
                'month', extract(month from s.m at time zone 'UTC')::int - 1,
                'amount', coalesce(mo.amount, 0)
            )
            order by s.m
        ),
        '[]'::jsonb
    )
      into v_result
      from series s
      left join monthly mo
        on mo.ym = to_char(s.m at time zone 'UTC', 'YYYY-MM');

    return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.read_debt_aging_thresholds()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_tenant uuid;
    v_grace integer;
    v_yellow integer;
    v_red integer;
    v_active integer;
    v_amount_yellow numeric;
    v_amount_red numeric;
    v_severe numeric;
    v_msg_green text;
    v_msg_yellow text;
    v_msg_orange text;
    v_msg_red text;
begin
    -- The SAME staff gate as the aging surface itself (0111/0125/0133/0138) —
    -- the thresholds are the aging audience's operational config, and the
    -- system_settings RLS (0024) stays untouched.
    if not public.has_any_role(array['super_admin', 'financial_officer', 'support_staff']) then
        raise exception 'forbidden: debt thresholds are a staff surface';
    end if;

    v_tenant := public.current_tenant_id();
    if v_tenant is null then
        raise exception 'forbidden: no tenant context';
    end if;

    select t.grace_period_days, t.yellow_days, t.red_days, t.active_payer_grace_days
      into v_grace, v_yellow, v_red, v_active
      from public.debt_aging_thresholds(v_tenant) t;

    -- T-469 (DEBT-103): the AMOUNT dimension + the level messages — read
    -- directly from system_settings (documented defaults when missing).
    -- T-502 (DEBT-104): + the SEVERE-DEBT edge (the console's quick query).
    select
        coalesce(min(case when s.key = 'debt.amount_threshold_yellow_dzd'
                          then (s.value #>> '{}')::numeric end), 20000),
        coalesce(min(case when s.key = 'debt.amount_threshold_red_dzd'
                          then (s.value #>> '{}')::numeric end), 60000),
        coalesce(min(case when s.key = 'debt.severe_debt_dzd'
                          then (s.value #>> '{}')::numeric end), 40000)
      into v_amount_yellow, v_amount_red, v_severe
      from public.system_settings s
     where s.tenant_id = v_tenant
       and s.category = 'debt'
       and s.key in ('debt.amount_threshold_yellow_dzd', 'debt.amount_threshold_red_dzd',
                     'debt.severe_debt_dzd');

    select
        coalesce(max(case when s.key = 'debt.level_message_green'    then s.value #>> '{}' end), ''),
        coalesce(max(case when s.key = 'debt.level_message_yellow'   then s.value #>> '{}' end), ''),
        coalesce(max(case when s.key = 'debt.level_message_orange'   then s.value #>> '{}' end), ''),
        coalesce(max(case when s.key = 'debt.level_message_red'      then s.value #>> '{}' end), '')
      into v_msg_green, v_msg_yellow, v_msg_orange, v_msg_red
      from public.system_settings s
     where s.tenant_id = v_tenant
       and s.category = 'debt'
       and s.key in ('debt.level_message_green', 'debt.level_message_yellow',
                     'debt.level_message_orange', 'debt.level_message_red');

    return jsonb_build_object(
        'gracePeriodDays', coalesce(v_grace, 5),
        'yellowDays', coalesce(v_yellow, 15),
        'redDays', coalesce(v_red, 60),
        'activePayerGraceDays', coalesce(v_active, 15),
        -- T-469 (DEBT-103): the amount edges (0 = the classification is
        -- disabled — every amount is amount-green) + the per-level messages
        -- (empty = the canonical engine text stands).
        'amountYellowDzd', coalesce(v_amount_yellow, 20000),
        'amountRedDzd', coalesce(v_amount_red, 60000),
        -- T-502 (DEBT-104): the console's severe-debt quick-query edge
        -- (default 40 000 — the previously hardcoded value).
        'severeDebtDzd', coalesce(v_severe, 40000),
        'levelMessages', jsonb_build_object(
            'green', coalesce(v_msg_green, ''),
            'yellow', coalesce(v_msg_yellow, ''),
            'orange', coalesce(v_msg_orange, ''),
            'red', coalesce(v_msg_red, '')
        )
    );
end;
$function$

